import { TriviaQuestion } from '../trivia-types'

export const MUSIC_QUESTIONS: TriviaQuestion[] = [
  { id: 'mus-1', category: 'music', difficulty: 'easy', question: 'What rock band is known for hits like "Stairway to Heaven" and "Whole Lotta Love"?', answer: 'Led Zeppelin', options: ['Led Zeppelin', 'Deep Purple', 'Black Sabbath', 'The Who'], explanation: 'Led Zeppelin formed in London in 1968 and is considered one of the greatest rock bands of all time. "Stairway to Heaven" is one of the most-played songs in radio history despite never being released as a single.' },
  { id: 'mus-2', category: 'music', difficulty: 'easy', question: 'What is the best-selling album of all time worldwide?', answer: 'Thriller by Michael Jackson', options: ['Back in Black by AC/DC', 'Thriller by Michael Jackson', 'The Dark Side of the Moon by Pink Floyd', 'Abbey Road by The Beatles'], explanation: 'Thriller has sold an estimated 66-70 million copies worldwide since its 1982 release. It produced seven top-10 singles on the Billboard Hot 100.' },
  { id: 'mus-3', category: 'music', difficulty: 'easy', question: 'Which classical composer became deaf later in life but continued to compose?', answer: 'Ludwig van Beethoven', options: ['Wolfgang Amadeus Mozart', 'Johann Sebastian Bach', 'Ludwig van Beethoven', 'Frederic Chopin'], explanation: 'Beethoven began losing his hearing around age 28 and was almost completely deaf by his mid-40s. He composed some of his greatest works, including the Ninth Symphony, while profoundly deaf.' },
  { id: 'mus-4', category: 'music', difficulty: 'easy', question: 'What British band released the albums "Abbey Road" and "Let It Be"?', answer: 'The Beatles', options: ['The Rolling Stones', 'The Beatles', 'The Who', 'The Kinks'], explanation: 'The Beatles are the best-selling music act of all time. Abbey Road\'s cover, featuring the four members crossing a zebra crossing, became one of the most iconic and imitated album covers in history.' },
  { id: 'mus-5', category: 'music', difficulty: 'easy', question: 'What instrument has 88 keys?', answer: 'Piano', options: ['Organ', 'Piano', 'Accordion', 'Harpsichord'], explanation: 'A standard modern piano has 88 keys: 52 white and 36 black. The piano was invented around 1700 by Bartolomeo Cristofori in Italy.' },
  { id: 'mus-6', category: 'music', difficulty: 'easy', question: 'Who is known as the "King of Pop"?', answer: 'Michael Jackson', options: ['Prince', 'Michael Jackson', 'Elvis Presley', 'Stevie Wonder'], explanation: 'Michael Jackson earned the title "King of Pop" and is one of the most significant cultural figures of the 20th century. His moonwalk dance move, first performed on TV in 1983, became his signature.' },
  { id: 'mus-7', category: 'music', difficulty: 'easy', question: 'Who is known as the "King of Rock and Roll"?', answer: 'Elvis Presley', options: ['Chuck Berry', 'Little Richard', 'Elvis Presley', 'Jerry Lee Lewis'], explanation: 'Elvis Presley rose to fame in the 1950s and is one of the best-selling solo music artists of all time. His home, Graceland in Memphis, Tennessee, is the second most-visited private home in the US after the White House.' },
  { id: 'mus-8', category: 'music', difficulty: 'easy', question: 'What genre of music originated in New Orleans in the late 19th and early 20th centuries?', answer: 'Jazz', options: ['Blues', 'Jazz', 'Rock and Roll', 'Country'], explanation: 'Jazz developed from a mix of African American musical traditions including blues, ragtime, and brass band marches. Louis Armstrong was one of its earliest and most influential soloists.' },
  { id: 'mus-9', category: 'music', difficulty: 'easy', question: 'What song by Queen features the lyrics "Is this the real life? Is this just fantasy?"', answer: 'Bohemian Rhapsody', options: ['We Will Rock You', 'Bohemian Rhapsody', 'Somebody to Love', 'Don\'t Stop Me Now'], explanation: 'Bohemian Rhapsody was released in 1975 and runs nearly six minutes with no chorus. It returned to #1 on the charts in 2018 after the release of the biographical film of the same name.' },
  { id: 'mus-10', category: 'music', difficulty: 'easy', question: 'How many strings does a standard guitar have?', answer: '6', options: ['4', '5', '6', '8'], explanation: 'A standard guitar has six strings tuned to E-A-D-G-B-E from lowest to highest. A bass guitar typically has four strings, tuned an octave lower than the bottom four guitar strings.' },
  { id: 'mus-11', category: 'music', difficulty: 'easy', question: 'What does "R&B" stand for in music?', answer: 'Rhythm and Blues', options: ['Rock and Ballad', 'Rhythm and Blues', 'Rap and Bass', 'Reggae and Blues'], explanation: 'The term Rhythm and Blues was coined in 1947 by Jerry Wexler at Billboard magazine. It replaced the outdated and offensive term "race music" to describe music made primarily by African American artists.' },
  { id: 'mus-12', category: 'music', difficulty: 'easy', question: 'What Elton John song was rewritten as a tribute to Princess Diana after her death in 1997?', answer: 'Candle in the Wind', options: ['Your Song', 'Candle in the Wind', 'Rocket Man', 'Tiny Dancer'], explanation: 'The original "Candle in the Wind" (1973) was written about Marilyn Monroe. The 1997 version, "Candle in the Wind 1997," became the best-selling physical single of all time with over 33 million copies sold.' },
  { id: 'mus-13', category: 'music', difficulty: 'easy', question: 'Which country music legend is known as "The Man in Black"?', answer: 'Johnny Cash', options: ['Hank Williams', 'Johnny Cash', 'Willie Nelson', 'Waylon Jennings'], explanation: 'Johnny Cash earned the nickname from his habit of wearing all-black clothing at performances. He explained in his song "Man in Black" that he wore it in sympathy for the poor and downtrodden.' },
  { id: 'mus-14', category: 'music', difficulty: 'easy', question: 'What Motown group featured Diana Ross as lead singer?', answer: 'The Supremes', options: ['The Temptations', 'The Supremes', 'The Marvelettes', 'Martha and the Vandellas'], explanation: 'The Supremes were Motown\'s most successful act in the 1960s, scoring 12 number-one singles. Diana Ross left the group in 1970 to pursue a solo career.' },
  { id: 'mus-15', category: 'music', difficulty: 'easy', question: 'What is the musical term for how fast or slow a piece of music is played?', answer: 'Tempo', options: ['Pitch', 'Tempo', 'Dynamics', 'Timbre'], explanation: 'Tempo is measured in beats per minute (BPM). Common tempo markings include Largo (slow), Andante (walking pace), Allegro (fast), and Presto (very fast).' },
  { id: 'mus-16', category: 'music', difficulty: 'easy', question: 'Which pop star is known as the "Queen of Pop"?', answer: 'Madonna', options: ['Whitney Houston', 'Beyonce', 'Madonna', 'Cher'], explanation: 'Madonna has sold over 300 million records worldwide, making her the best-selling female music artist of all time. She has continuously reinvented her image over a career spanning more than four decades.' },
  { id: 'mus-17', category: 'music', difficulty: 'easy', question: 'What instrument does a drummer typically play with?', answer: 'Drumsticks', options: ['Mallets', 'Brushes', 'Drumsticks', 'Bows'], explanation: 'While drumsticks are the most common, drummers also use brushes for jazz, mallets for softer tones, and rods (bundled dowels) for medium volume. Most drumsticks are made from hickory wood.' },
  { id: 'mus-18', category: 'music', difficulty: 'easy', question: 'What band performed at the halftime show of the first-ever Super Bowl halftime show to feature a rock act, in 2002?', answer: 'U2', options: ['The Rolling Stones', 'U2', 'Aerosmith', 'Bruce Springsteen'], explanation: 'U2 performed at Super Bowl XXXVI in February 2002 with a tribute to 9/11 victims. Before this, halftime shows typically featured marching bands and variety acts.' },
  { id: 'mus-19', category: 'music', difficulty: 'easy', question: 'What Rolling Stones song features the lyrics "I can\'t get no satisfaction"?', answer: '(I Can\'t Get No) Satisfaction', options: ['Paint It Black', 'Sympathy for the Devil', '(I Can\'t Get No) Satisfaction', 'Jumpin\' Jack Flash'], explanation: 'Released in 1965, "Satisfaction" became The Rolling Stones\' first number-one hit in the US. Keith Richards has said the guitar riff came to him in a dream.' },
  { id: 'mus-20', category: 'music', difficulty: 'easy', question: 'What music streaming service was founded in Sweden in 2006?', answer: 'Spotify', options: ['Apple Music', 'Spotify', 'Pandora', 'Tidal'], explanation: 'Spotify was founded by Daniel Ek and Martin Lorentzon in Stockholm. It launched to the public in 2008 and has grown to become the world\'s largest music streaming service.' },
  { id: 'mus-21', category: 'music', difficulty: 'easy', question: 'Which composer wrote "The Four Seasons"?', answer: 'Antonio Vivaldi', options: ['Johann Sebastian Bach', 'Antonio Vivaldi', 'George Frideric Handel', 'Wolfgang Amadeus Mozart'], explanation: 'Vivaldi composed The Four Seasons around 1718-1720 as part of a larger set of violin concertos. Each concerto represents a season and was accompanied by a sonnet, possibly written by Vivaldi himself.' },
  { id: 'mus-22', category: 'music', difficulty: 'easy', question: 'What does "MTV" stand for?', answer: 'Music Television', options: ['Music Television', 'Modern Television', 'Media Television', 'Music and Talent Video'], explanation: 'MTV launched on August 1, 1981, with the words "Ladies and gentlemen, rock and roll." The first music video played was "Video Killed the Radio Star" by The Buggles.' },
  { id: 'mus-23', category: 'music', difficulty: 'easy', question: 'What famous music festival took place on a dairy farm in upstate New York in 1969?', answer: 'Woodstock', options: ['Monterey Pop', 'Woodstock', 'Altamont', 'Coachella'], explanation: 'Woodstock attracted an estimated 400,000 people over three days in August 1969. Despite the name, it actually took place in Bethel, New York, about 60 miles from the town of Woodstock.' },
  { id: 'mus-24', category: 'music', difficulty: 'easy', question: 'What hip hop group released the album "Licensed to Ill" in 1986?', answer: 'Beastie Boys', options: ['Run-DMC', 'Beastie Boys', 'Public Enemy', 'N.W.A.'], explanation: 'Licensed to Ill was the first rap album to reach #1 on the Billboard 200. The Beastie Boys were among the first white hip hop groups to achieve mainstream success.' },
  { id: 'mus-25', category: 'music', difficulty: 'easy', question: 'In music notation, how many beats does a whole note receive in 4/4 time?', answer: '4', options: ['1', '2', '3', '4'], explanation: 'A whole note fills an entire measure in 4/4 time, receiving four beats. A half note gets two beats, a quarter note gets one beat, and an eighth note gets half a beat.' },
  { id: 'mus-26', category: 'music', difficulty: 'easy', question: 'What artist released the album "Purple Rain" in 1984?', answer: 'Prince', options: ['Prince', 'Michael Jackson', 'David Bowie', 'Stevie Wonder'], explanation: 'Purple Rain was both a studio album and the soundtrack to Prince\'s semi-autobiographical film of the same name. It spent 24 consecutive weeks at #1 on the Billboard 200.' },
  { id: 'mus-27', category: 'music', difficulty: 'easy', question: 'What British rock band features Mick Jagger as lead vocalist?', answer: 'The Rolling Stones', options: ['The Beatles', 'The Rolling Stones', 'The Who', 'Led Zeppelin'], explanation: 'The Rolling Stones formed in London in 1962 and are still performing decades later. They are often called "The World\'s Greatest Rock and Roll Band."' },
  { id: 'mus-28', category: 'music', difficulty: 'easy', question: 'Which Nirvana song opens with the lyrics "Load up on guns, bring your friends"?', answer: 'Smells Like Teen Spirit', options: ['Come as You Are', 'Smells Like Teen Spirit', 'In Bloom', 'Lithium'], explanation: 'Smells Like Teen Spirit (1991) is widely credited with bringing grunge and alternative rock into the mainstream. The song\'s name came from a deodorant brand, Teen Spirit, which a friend had written on Kurt Cobain\'s wall.' },
  { id: 'mus-29', category: 'music', difficulty: 'easy', question: 'What legendary guitarist was known for playing a right-handed guitar upside down and left-handed?', answer: 'Jimi Hendrix', options: ['Eric Clapton', 'Jimi Hendrix', 'Jimmy Page', 'Carlos Santana'], explanation: 'Jimi Hendrix was left-handed and played a right-handed Fender Stratocaster flipped upside down, restringing it for left-handed play. He is widely regarded as the greatest electric guitarist in history.' },
  { id: 'mus-30', category: 'music', difficulty: 'easy', question: 'What Whitney Houston song became one of the best-selling singles of all time after being featured in The Bodyguard?', answer: 'I Will Always Love You', options: ['Greatest Love of All', 'I Wanna Dance with Somebody', 'I Will Always Love You', 'How Will I Know'], explanation: '"I Will Always Love You" was originally written and recorded by Dolly Parton in 1973. Houston\'s 1992 version spent 14 weeks at #1 on the Billboard Hot 100.' },
  { id: 'mus-31', category: 'music', difficulty: 'easy', question: 'What band is known for the songs "Hotel California" and "Take It Easy"?', answer: 'Eagles', options: ['Fleetwood Mac', 'Eagles', 'Lynyrd Skynyrd', 'Steely Dan'], explanation: 'The Eagles\' Greatest Hits (1971-1975) was the first album ever certified platinum and is one of the best-selling albums in US history. "Hotel California" is one of the most analyzed songs in rock music.' },
  { id: 'mus-32', category: 'music', difficulty: 'easy', question: 'What is the highest female singing voice type?', answer: 'Soprano', options: ['Alto', 'Soprano', 'Mezzo-soprano', 'Contralto'], explanation: 'The soprano range typically extends from middle C to two octaves above. Famous sopranos include Maria Callas, Renee Fleming, and Luciano Pavarotti\'s frequent duet partner, Joan Sutherland.' },
  { id: 'mus-33', category: 'music', difficulty: 'easy', question: 'What classic rock band released "Dark Side of the Moon," which spent a record 937 weeks on the Billboard 200?', answer: 'Pink Floyd', options: ['Led Zeppelin', 'Pink Floyd', 'Genesis', 'Yes'], explanation: 'The Dark Side of the Moon (1973) is one of the best-selling albums of all time with over 45 million copies sold. Its iconic prism cover was designed by Storm Thorgerson of the design group Hipgnosis.' },
  { id: 'mus-34', category: 'music', difficulty: 'easy', question: 'What Taylor Swift album marked her transition from country to pop music?', answer: '1989', options: ['Red', '1989', 'Reputation', 'Fearless'], explanation: '1989, released in 2014, was Swift\'s first official pop album after the transitional Red. It sold over 1.287 million copies in its first week, making it the biggest debut sales week since 2002.' },
  { id: 'mus-35', category: 'music', difficulty: 'medium', question: 'What Beethoven symphony is commonly known as the "Choral" symphony?', answer: 'Symphony No. 9', options: ['Symphony No. 5', 'Symphony No. 7', 'Symphony No. 9', 'Symphony No. 3'], explanation: 'Beethoven\'s Ninth Symphony (1824) was the first major symphony to include vocal soloists and a choir. Its final movement features a setting of Friedrich Schiller\'s poem "Ode to Joy," which became the anthem of the European Union.' },
  { id: 'mus-36', category: 'music', difficulty: 'medium', question: 'What one-hit wonder band released "Come On Eileen" in 1982?', answer: 'Dexys Midnight Runners', options: ['A Flock of Seagulls', 'Kajagoogoo', 'Dexys Midnight Runners', 'Soft Cell'], explanation: '"Come On Eileen" reached #1 in both the UK and US. While Dexys Midnight Runners had other UK hits, they are considered a one-hit wonder in the United States.' },
  { id: 'mus-37', category: 'music', difficulty: 'medium', question: 'What rapper\'s real name is Marshall Bruce Mathers III?', answer: 'Eminem', options: ['Jay-Z', 'Eminem', 'Kanye West', '50 Cent'], explanation: 'Eminem\'s stage name comes from his initials M&M (Marshall Mathers). His album The Marshall Mathers LP sold 1.76 million copies in its first week, a record for a solo artist at the time.' },
  { id: 'mus-38', category: 'music', difficulty: 'medium', question: 'What was the first music video played on MTV?', answer: 'Video Killed the Radio Star by The Buggles', options: ['Thriller by Michael Jackson', 'Video Killed the Radio Star by The Buggles', 'Money for Nothing by Dire Straits', 'Take on Me by a-ha'], explanation: '"Video Killed the Radio Star" by The Buggles aired at 12:01 AM on August 1, 1981, marking MTV\'s launch. The song had been a #1 hit in the UK in 1979 but only reached #40 in the US.' },
  { id: 'mus-39', category: 'music', difficulty: 'medium', question: 'What 1970s band featured the brothers Barry, Robin, and Maurice Gibb?', answer: 'Bee Gees', options: ['The Osmonds', 'Bee Gees', 'The Jackson 5', 'Hanson'], explanation: 'The Bee Gees dominated the disco era with hits like "Stayin\' Alive" and "How Deep Is Your Love." They are one of the best-selling music artists of all time with over 220 million records sold.' },
  { id: 'mus-40', category: 'music', difficulty: 'medium', question: 'What is the term for the distance between two musical notes?', answer: 'Interval', options: ['Chord', 'Scale', 'Interval', 'Octave'], explanation: 'Musical intervals are classified by the number of scale steps between notes (e.g., a third, a fifth). They can be major, minor, perfect, augmented, or diminished.' },
  { id: 'mus-41', category: 'music', difficulty: 'medium', question: 'Which member of The Beatles was assassinated in New York City in 1980?', answer: 'John Lennon', options: ['Paul McCartney', 'George Harrison', 'John Lennon', 'Ringo Starr'], explanation: 'John Lennon was shot by Mark David Chapman outside his apartment at the Dakota building on December 8, 1980. His song "Imagine" became an enduring anthem for peace.' },
  { id: 'mus-42', category: 'music', difficulty: 'medium', question: 'What Grammy Award category has been won the most times by a single artist, and who holds the record?', answer: 'Album of the Year, won by several artists three or fewer times; Beyonce holds the overall Grammy record with 35 wins', options: ['Song of the Year — Paul Simon', 'Album of the Year, won by several artists three or fewer times; Beyonce holds the overall Grammy record with 35 wins', 'Best Pop Vocal — Adele', 'Record of the Year — Stevie Wonder'], explanation: 'Beyonce surpassed Georg Solti\'s longstanding record of 31 Grammys and reached 35 wins at the 2025 ceremony. No artist has won Album of the Year more than three times — that distinction is shared by Frank Sinatra, Stevie Wonder, and Paul Simon.' },
  { id: 'mus-43', category: 'music', difficulty: 'medium', question: 'What instrument is Yo-Yo Ma famous for playing?', answer: 'Cello', options: ['Violin', 'Cello', 'Viola', 'Double bass'], explanation: 'Yo-Yo Ma is a French-born Chinese American cellist who began performing at age four. He has won 19 Grammy Awards and is known for making classical music accessible to wider audiences.' },
  { id: 'mus-44', category: 'music', difficulty: 'medium', question: 'What hip hop album by Nas is frequently cited as one of the greatest rap albums of all time and was released in 1994?', answer: 'Illmatic', options: ['Ready to Die', 'Illmatic', 'Enter the Wu-Tang', 'The Chronic'], explanation: 'Illmatic was Nas\'s debut album, recorded when he was just 20 years old. Despite initially modest sales, it is now universally regarded as a masterpiece of hip hop.' },
  { id: 'mus-45', category: 'music', difficulty: 'medium', question: 'What is the name of the musical scale that uses only five notes per octave?', answer: 'Pentatonic scale', options: ['Chromatic scale', 'Pentatonic scale', 'Whole tone scale', 'Blues scale'], explanation: 'The pentatonic scale appears in folk music traditions worldwide, from Chinese music to Celtic music to blues. Bobby McFerrin famously demonstrated its universality in a TED talk by getting the audience to sing along instinctively.' },
  { id: 'mus-46', category: 'music', difficulty: 'medium', question: 'What Fleetwood Mac album, released in 1977, became one of the best-selling albums of all time?', answer: 'Rumours', options: ['Fleetwood Mac', 'Rumours', 'Tusk', 'Tango in the Night'], explanation: 'Rumours has sold over 40 million copies worldwide. It was recorded during a period of extreme personal turmoil — two couples in the band were breaking up simultaneously, which fueled the album\'s emotional songwriting.' },
  { id: 'mus-47', category: 'music', difficulty: 'medium', question: 'What genre of music originated in the South Bronx in the 1970s?', answer: 'Hip hop', options: ['Disco', 'Hip hop', 'Punk rock', 'New wave'], explanation: 'Hip hop culture emerged from block parties in the South Bronx, pioneered by DJs like Kool Herc, Afrika Bambaataa, and Grandmaster Flash. It encompasses four elements: MCing, DJing, breakdancing, and graffiti art.' },
  { id: 'mus-48', category: 'music', difficulty: 'medium', question: 'What Bob Dylan song was a protest anthem of the 1960s civil rights movement?', answer: 'Blowin\' in the Wind', options: ['Like a Rolling Stone', 'Blowin\' in the Wind', 'The Times They Are a-Changin\'', 'Knockin\' on Heaven\'s Door'], explanation: 'Blowin\' in the Wind was released in 1962 on The Freewheelin\' Bob Dylan. Peter, Paul and Mary\'s cover version became a bigger hit, reaching #2 on the Billboard Hot 100.' },
  { id: 'mus-49', category: 'music', difficulty: 'medium', question: 'What composer wrote over 600 works in his short 35-year life, including "Eine kleine Nachtmusik"?', answer: 'Wolfgang Amadeus Mozart', options: ['Franz Schubert', 'Wolfgang Amadeus Mozart', 'Felix Mendelssohn', 'Frederic Chopin'], explanation: 'Mozart was a child prodigy who began composing at age five and performed for European royalty. Despite his enormous output and fame, he was buried in a common grave in Vienna, and the exact location of his remains is unknown.' },
  { id: 'mus-50', category: 'music', difficulty: 'medium', question: 'What Aretha Franklin song became an anthem for the feminist and civil rights movements?', answer: 'Respect', options: ['Natural Woman', 'Respect', 'Think', 'Chain of Fools'], explanation: '"Respect" was originally written and recorded by Otis Redding in 1965. Franklin\'s 1967 version completely transformed the song, adding the iconic "R-E-S-P-E-C-T" spelling.' },
  { id: 'mus-51', category: 'music', difficulty: 'medium', question: 'What record label, founded by Berry Gordy Jr. in 1959, launched the careers of The Supremes, The Temptations, and Stevie Wonder?', answer: 'Motown', options: ['Stax', 'Atlantic', 'Motown', 'Chess'], explanation: 'Motown Records was founded in Detroit, whose nickname "Motor City" inspired the label name. Its assembly-line approach to hit-making produced a distinctive sound that helped break down racial barriers in pop music.' },
  { id: 'mus-52', category: 'music', difficulty: 'medium', question: 'What Pink Floyd album features a giant inflatable pig on its cover?', answer: 'Animals', options: ['The Wall', 'Animals', 'Wish You Were Here', 'Atom Heart Mother'], explanation: 'The Animals cover shows an inflatable pig floating between the chimneys of Battersea Power Station in London. During the photo shoot, the pig broke free and drifted into Heathrow Airport\'s flight path, causing flights to be delayed.' },
  { id: 'mus-53', category: 'music', difficulty: 'medium', question: 'Who was the lead singer of The Doors?', answer: 'Jim Morrison', options: ['Robert Plant', 'Jim Morrison', 'Roger Daltrey', 'Freddie Mercury'], explanation: 'Jim Morrison was known for his poetic lyrics, charismatic stage presence, and self-destructive behavior. He died in Paris in 1971 at age 27, becoming one of the founding members of the "27 Club."' },
  { id: 'mus-54', category: 'music', difficulty: 'medium', question: 'What 1997 Radiohead album is often cited as one of the greatest albums ever made?', answer: 'OK Computer', options: ['The Bends', 'OK Computer', 'Kid A', 'In Rainbows'], explanation: 'OK Computer explored themes of alienation, technology, and modern life. It was recorded partly in actress Jane Seymour\'s 15th-century mansion, contributing to its atmospheric sound.' },
  { id: 'mus-55', category: 'music', difficulty: 'medium', question: 'What key is traditionally considered the "saddest" key in classical music?', answer: 'D minor', options: ['C minor', 'D minor', 'E minor', 'A minor'], explanation: 'D minor has been described as the saddest of all keys, a characterization notably popularized by the movie Spinal Tap. Beethoven\'s Ninth Symphony and Mozart\'s Requiem are both written in D minor.' },
  { id: 'mus-56', category: 'music', difficulty: 'medium', question: 'What one-hit wonder is Lipps Inc known for?', answer: 'Funkytown', options: ['Funkytown', 'Whip It', 'Tainted Love', 'Der Komissar'], explanation: '"Funkytown" reached #1 on the Billboard Hot 100 in 1980 and has been covered and sampled extensively. The group was led by Steven Greenberg, who also produced the track.' },
  { id: 'mus-57', category: 'music', difficulty: 'medium', question: 'In a standard orchestra, which section typically has the most players?', answer: 'Strings', options: ['Woodwinds', 'Brass', 'Strings', 'Percussion'], explanation: 'The string section typically comprises about 60 of the roughly 100 musicians in a full symphony orchestra. This larger number is needed because string instruments produce less volume individually compared to brass and woodwinds.' },
  { id: 'mus-58', category: 'music', difficulty: 'medium', question: 'What song holds the record for the most weeks at #1 on the Billboard Hot 100?', answer: 'Old Town Road by Lil Nas X', options: ['One Sweet Day by Mariah Carey', 'Despacito by Luis Fonsi', 'Old Town Road by Lil Nas X', 'Shape of You by Ed Sheeran'], explanation: '"Old Town Road" by Lil Nas X (featuring Billy Ray Cyrus) spent 19 weeks at #1 in 2019, breaking the previous record of 16 weeks. The song went viral on TikTok and sparked a debate about genre classification between country and hip hop.' },
  { id: 'mus-59', category: 'music', difficulty: 'medium', question: 'What is the name of the annual music festival held in the California desert, known for its art installations and celebrity sightings?', answer: 'Coachella', options: ['Burning Man', 'Coachella', 'Bonnaroo', 'Lollapalooza'], explanation: 'The Coachella Valley Music and Arts Festival was first held in 1999 in Indio, California, and has been held annually since 2001. It expanded to two consecutive weekends in 2012 due to high demand.' },
  { id: 'mus-60', category: 'music', difficulty: 'medium', question: 'Which Bach composition is famous for its opening cello solo and is often played at weddings?', answer: 'Cello Suite No. 1 in G Major', options: ['Air on the G String', 'Cello Suite No. 1 in G Major', 'Toccata and Fugue in D Minor', 'Brandenburg Concerto No. 3'], explanation: 'The Prelude from Bach\'s Cello Suite No. 1 is one of the most recognized pieces of classical music. Pablo Casals is credited with rediscovering and popularizing the Cello Suites in the early 20th century.' },
  { id: 'mus-61', category: 'music', difficulty: 'medium', question: 'What reggae musician released the album "Legend," which became the best-selling reggae album of all time?', answer: 'Bob Marley', options: ['Peter Tosh', 'Bob Marley', 'Jimmy Cliff', 'Toots Hibbert'], explanation: 'Legend is a posthumous greatest hits compilation released in 1984, three years after Marley\'s death. It has sold over 33 million copies worldwide and introduced reggae to a massive global audience.' },
  { id: 'mus-62', category: 'music', difficulty: 'medium', question: 'What is the term for a group of three or more notes played simultaneously?', answer: 'Chord', options: ['Interval', 'Chord', 'Arpeggio', 'Scale'], explanation: 'The most basic chord is a triad, consisting of three notes. Common chord types include major (happy-sounding), minor (sad-sounding), diminished, and augmented.' },
  { id: 'mus-63', category: 'music', difficulty: 'medium', question: 'What concept album by The Who tells the story of a deaf, dumb, and blind boy who becomes a pinball champion?', answer: 'Tommy', options: ['Quadrophenia', 'Tommy', 'Who\'s Next', 'The Who Sell Out'], explanation: 'Tommy (1969) is often called the first rock opera. It was later adapted into a film by Ken Russell in 1975 and a Broadway musical in 1993.' },
  { id: 'mus-64', category: 'music', difficulty: 'medium', question: 'What artist\'s 2016 album "Lemonade" was a visual album exploring themes of infidelity and Black womanhood?', answer: 'Beyonce', options: ['Rihanna', 'Beyonce', 'Solange', 'Alicia Keys'], explanation: 'Lemonade debuted as an HBO film before the album was released. It received widespread critical acclaim and became a cultural touchstone, blending genres from country to rock to hip hop.' },
  { id: 'mus-65', category: 'music', difficulty: 'medium', question: 'What Chopin composition form is a nocturnal piece, typically for solo piano?', answer: 'Nocturne', options: ['Etude', 'Nocturne', 'Polonaise', 'Mazurka'], explanation: 'Chopin composed 21 nocturnes, though the form was pioneered by Irish composer John Field. Chopin\'s Nocturne in E-flat major, Op. 9, No. 2 is one of his most famous and frequently performed works.' },
  { id: 'mus-66', category: 'music', difficulty: 'medium', question: 'What British band\'s debut album "Definitely Maybe" and follow-up "What\'s the Story Morning Glory?" defined Britpop?', answer: 'Oasis', options: ['Blur', 'Oasis', 'Pulp', 'Suede'], explanation: 'Oasis, led by brothers Liam and Noel Gallagher, were at the center of the 1990s Britpop movement. Their rivalry with Blur, known as the "Battle of Britpop," dominated UK music headlines in 1995.' },
  { id: 'mus-67', category: 'music', difficulty: 'medium', question: 'What is the musical term for gradually getting louder?', answer: 'Crescendo', options: ['Forte', 'Crescendo', 'Fortissimo', 'Sforzando'], explanation: 'Crescendo comes from the Italian word meaning "growing." Its opposite, getting gradually softer, is called decrescendo or diminuendo.' },
  { id: 'mus-68', category: 'music', difficulty: 'medium', question: 'What country artist crossed over to pop with the song "9 to 5" and also starred in the film of the same name?', answer: 'Dolly Parton', options: ['Loretta Lynn', 'Dolly Parton', 'Tammy Wynette', 'Reba McEntire'], explanation: 'Dolly Parton wrote "9 to 5" on set using her acrylic nails as percussion. She is also known for her philanthropy, including the Imagination Library, which has gifted over 200 million books to children.' },
  { id: 'mus-69', category: 'music', difficulty: 'medium', question: 'What grunge band\'s lead singer, Layne Staley, struggled with addiction and was found dead in 2002?', answer: 'Alice in Chains', options: ['Soundgarden', 'Alice in Chains', 'Pearl Jam', 'Stone Temple Pilots'], explanation: 'Layne Staley was known for his distinctive vocal harmonies with guitarist Jerry Cantrell. Alice in Chains was a key band in the Seattle grunge scene alongside Nirvana, Pearl Jam, and Soundgarden.' },
  { id: 'mus-70', category: 'music', difficulty: 'medium', question: 'What Kanye West album, released in 2010, was recorded primarily with a maximalist orchestral approach?', answer: 'My Beautiful Dark Twisted Fantasy', options: ['Graduation', 'My Beautiful Dark Twisted Fantasy', '808s & Heartbreak', 'Yeezus'], explanation: 'My Beautiful Dark Twisted Fantasy is widely considered Kanye West\'s magnum opus and one of the greatest albums of the 2010s. It featured collaborations with Jay-Z, Bon Iver, Rihanna, and many others.' },
  { id: 'mus-71', category: 'music', difficulty: 'medium', question: 'What instrument family does the saxophone belong to?', answer: 'Woodwinds', options: ['Brass', 'Woodwinds', 'Strings', 'Percussion'], explanation: 'Despite being made of brass, the saxophone is classified as a woodwind because it uses a single reed to produce sound. It was invented by Adolphe Sax in the 1840s.' },
  { id: 'mus-72', category: 'music', difficulty: 'medium', question: 'What Bruce Springsteen album, released in 1984, became one of the best-selling albums in US history?', answer: 'Born in the U.S.A.', options: ['Born to Run', 'Born in the U.S.A.', 'The River', 'Nebraska'], explanation: 'Born in the U.S.A. produced seven top-10 singles and sold over 30 million copies worldwide. The title track is frequently misinterpreted as patriotic, but it is actually a critical commentary on the treatment of Vietnam veterans.' },
  { id: 'mus-73', category: 'music', difficulty: 'medium', question: 'What was the first rap single to reach #1 on the Billboard Hot 100?', answer: 'Rapture by Blondie', options: ['Rapper\'s Delight by The Sugarhill Gang', 'Rapture by Blondie', 'Walk This Way by Run-DMC', 'It\'s Like That by Run-DMC'], explanation: 'Blondie\'s "Rapture" reached #1 in 1981, making it the first song with rap vocals to top the Hot 100. It featured Debbie Harry rapping and name-checked hip hop pioneer Fab Five Freddy.' },
  { id: 'mus-74', category: 'music', difficulty: 'medium', question: 'What annual awards show is considered the most prestigious in the music industry?', answer: 'Grammy Awards', options: ['MTV Video Music Awards', 'American Music Awards', 'Grammy Awards', 'Billboard Music Awards'], explanation: 'The Grammy Awards have been presented by the Recording Academy since 1959. The first ceremony was held at the Beverly Hilton Hotel in Los Angeles, honoring recordings from 1958.' },
  { id: 'mus-75', category: 'music', difficulty: 'medium', question: 'What David Bowie alter ego performed the album "The Rise and Fall of Ziggy Stardust and the Spiders from Mars"?', answer: 'Ziggy Stardust', options: ['Aladdin Sane', 'The Thin White Duke', 'Ziggy Stardust', 'Major Tom'], explanation: 'Bowie adopted the Ziggy Stardust persona in 1972, complete with flamboyant costumes and androgynous appearance. He "retired" the character in a famous 1973 concert at London\'s Hammersmith Odeon.' },
  { id: 'mus-76', category: 'music', difficulty: 'medium', question: 'What Miles Davis album, released in 1959, is the best-selling jazz album of all time?', answer: 'Kind of Blue', options: ['Bitches Brew', 'Kind of Blue', 'Birth of the Cool', 'Sketches of Spain'], explanation: 'Kind of Blue has sold over 5 million copies in the US alone. It pioneered modal jazz, using musical modes rather than complex chord changes as the basis for improvisation.' },
  { id: 'mus-77', category: 'music', difficulty: 'medium', question: 'What band released "Nevermind" in 1991, which displaced Michael Jackson\'s "Dangerous" from #1?', answer: 'Nirvana', options: ['Pearl Jam', 'Nirvana', 'Soundgarden', 'Alice in Chains'], explanation: 'Nevermind\'s rise to #1 is often cited as the moment grunge displaced mainstream pop. Its baby-swimming-after-a-dollar-bill cover became one of the most recognizable album covers of all time.' },
  { id: 'mus-78', category: 'music', difficulty: 'medium', question: 'What is the standard tuning for a violin\'s four strings, from lowest to highest?', answer: 'G-D-A-E', options: ['E-A-D-G', 'G-D-A-E', 'C-G-D-A', 'D-A-E-B'], explanation: 'The violin strings are tuned in fifths: G3, D4, A4, E5. This is also the tuning for a mandolin, except the mandolin has doubled (paired) strings tuned to the same pitches.' },
  { id: 'mus-79', category: 'music', difficulty: 'medium', question: 'What southern rock band is known for the song "Free Bird"?', answer: 'Lynyrd Skynyrd', options: ['The Allman Brothers Band', 'Lynyrd Skynyrd', 'Molly Hatchet', 'The Marshall Tucker Band'], explanation: '"Free Bird" is famous for its extended guitar solo, which often runs over four minutes. Tragically, lead singer Ronnie Van Zant and guitarist Steve Gaines died in a plane crash in 1977.' },
  { id: 'mus-80', category: 'music', difficulty: 'medium', question: 'What pop group from the 1990s consisted of members Scary, Sporty, Ginger, Baby, and Posh?', answer: 'Spice Girls', options: ['Destiny\'s Child', 'TLC', 'Spice Girls', 'All Saints'], explanation: 'The Spice Girls\' debut single "Wannabe" (1996) reached #1 in 37 countries. They sold over 100 million records worldwide, making them the best-selling female group of all time.' },
  { id: 'mus-81', category: 'music', difficulty: 'medium', question: 'Which composer is known for his "Ride of the Valkyries," famously used in the film Apocalypse Now?', answer: 'Richard Wagner', options: ['Richard Strauss', 'Richard Wagner', 'Gustav Mahler', 'Johannes Brahms'], explanation: '"Ride of the Valkyries" is from Wagner\'s opera Die Walkure, part of his Ring Cycle. Wagner was revolutionary in his concept of the Gesamtkunstwerk, or "total work of art," combining music, drama, and visual spectacle.' },
  { id: 'mus-82', category: 'music', difficulty: 'medium', question: 'What was the "British Invasion" in music?', answer: 'A wave of British rock bands becoming popular in the US in the mid-1960s', options: ['British punk bands touring the US in 1977', 'A wave of British rock bands becoming popular in the US in the mid-1960s', 'The formation of the Spice Girls', 'British DJs dominating US dance clubs in the 1990s'], explanation: 'The British Invasion began with The Beatles\' appearance on The Ed Sullivan Show in February 1964. Other key bands included The Rolling Stones, The Kinks, The Who, and The Animals.' },
  { id: 'mus-83', category: 'music', difficulty: 'medium', question: 'What song by Toto, released in 1982, has experienced a massive resurgence as an internet meme?', answer: 'Africa', options: ['Rosanna', 'Africa', 'Hold the Line', 'I Won\'t Hold You Back'], explanation: '"Africa" reached #1 on the Billboard Hot 100 in 1983. It became a viral sensation in the 2010s, with Weezer eventually recording a cover version in 2018 after fan demand.' },
  { id: 'mus-84', category: 'music', difficulty: 'medium', question: 'What jazz musician was known as "Satchmo" and popularized "What a Wonderful World"?', answer: 'Louis Armstrong', options: ['Duke Ellington', 'Louis Armstrong', 'Charlie Parker', 'Dizzy Gillespie'], explanation: 'Louis Armstrong\'s gravelly voice and virtuosic trumpet playing made him one of the most influential figures in jazz history. "What a Wonderful World" (1967) has become one of the most played songs at graduations and memorials.' },
  { id: 'mus-85', category: 'music', difficulty: 'medium', question: 'What is the Blues scale made up of?', answer: 'The minor pentatonic scale plus a flat fifth', options: ['A major scale with a flat third', 'The minor pentatonic scale plus a flat fifth', 'A natural minor scale with a sharp fourth', 'The major pentatonic scale plus a flat seventh'], explanation: 'The added note (flat fifth or "blue note") gives the blues scale its characteristic tension. In the key of C, the blues scale is C-Eb-F-Gb-G-Bb-C.' },
  { id: 'mus-86', category: 'music', difficulty: 'medium', question: 'What Dr. Dre album, released in 1992, is credited with popularizing G-funk and West Coast hip hop?', answer: 'The Chronic', options: ['2001', 'The Chronic', 'Compton', 'No One Can Do It Better'], explanation: 'The Chronic featured heavy use of Parliament-Funkadelic samples and laid-back synthesizer melodies. It also introduced Snoop Dogg to the world, who appeared on several tracks.' },
  { id: 'mus-87', category: 'music', difficulty: 'medium', question: 'What genre of music combines elements of punk rock and ska, popularized by bands like The Specials and Madness?', answer: '2 Tone / Ska punk', options: ['New wave', '2 Tone / Ska punk', 'Post-punk', 'Mod revival'], explanation: 'The 2 Tone movement emerged in late 1970s England, named after the record label founded by Jerry Dammers of The Specials. It was notable for its multiracial bands and politically conscious lyrics.' },
  { id: 'mus-88', category: 'music', difficulty: 'medium', question: 'What legendary guitarist and singer wrote "Crossroads" and is known as the "King of the Delta Blues"?', answer: 'Robert Johnson', options: ['Muddy Waters', 'Robert Johnson', 'B.B. King', 'Howlin\' Wolf'], explanation: 'Robert Johnson recorded only 29 songs before his death at age 27 in 1938. Legend says he sold his soul to the devil at a Mississippi crossroads in exchange for his guitar skills.' },
  { id: 'mus-89', category: 'music', difficulty: 'hard', question: 'What is the term for the acoustical phenomenon where two notes played simultaneously produce a third, lower "phantom" tone?', answer: 'Combination tone (or difference tone)', options: ['Harmonic overtone', 'Sympathetic resonance', 'Combination tone (or difference tone)', 'Beat frequency'], explanation: 'The combination tone, first documented by violinist Giuseppe Tartini in 1714, occurs at the frequency equal to the difference between the two played notes. It is sometimes called a Tartini tone in his honor.' },
  { id: 'mus-90', category: 'music', difficulty: 'hard', question: 'What was the first commercially successful electric guitar, introduced by Fender in 1950?', answer: 'Fender Esquire/Broadcaster (later Telecaster)', options: ['Fender Stratocaster', 'Fender Esquire/Broadcaster (later Telecaster)', 'Gibson Les Paul', 'Fender Jazzmaster'], explanation: 'The Fender Esquire debuted in 1950 as a single-pickup model, followed by the two-pickup Broadcaster. Gretsch objected to the Broadcaster name (similar to their Broadkaster drums), so Fender renamed it the Telecaster.' },
  { id: 'mus-91', category: 'music', difficulty: 'hard', question: 'What concept in music theory describes the tendency of one chord to resolve to another, such as the V chord resolving to the I chord?', answer: 'Harmonic function', options: ['Voice leading', 'Harmonic function', 'Counterpoint', 'Cadential motion'], explanation: 'Harmonic function categorizes chords into three groups: tonic (stable, home), dominant (tension, wants to resolve), and predominant (prepares the dominant). The V-I resolution is the strongest cadence in tonal music.' },
  { id: 'mus-92', category: 'music', difficulty: 'hard', question: 'What pioneering electronic instrument, invented in 1920, is played without physical contact?', answer: 'Theremin', options: ['Moog synthesizer', 'Theremin', 'Ondes Martenot', 'Mellotron'], explanation: 'The theremin was invented by Russian physicist Leon Theremin. The player controls pitch and volume by moving their hands near two metal antennas. It was famously used in the Beach Boys\' "Good Vibrations" (though that was actually an Electro-Theremin).' },
  { id: 'mus-93', category: 'music', difficulty: 'hard', question: 'What Philip Glass opera, premiered in 1976, is considered a landmark of minimalist music?', answer: 'Einstein on the Beach', options: ['Satyagraha', 'Einstein on the Beach', 'Akhnaten', 'The Voyage'], explanation: 'Einstein on the Beach, created with director Robert Wilson, runs approximately five hours with no intermission. Audiences are encouraged to leave and return freely. It features no traditional narrative, instead using repetitive musical structures and abstract imagery.' },
  { id: 'mus-94', category: 'music', difficulty: 'hard', question: 'What technique, used extensively by Bach, involves two or more independent melodic lines played simultaneously?', answer: 'Counterpoint', options: ['Harmony', 'Counterpoint', 'Polyphony', 'Homophony'], explanation: 'Counterpoint is the art of combining melodies. Bach\'s The Art of Fugue and The Well-Tempered Clavier are considered the supreme achievements of contrapuntal writing, with each voice maintaining its own identity while fitting harmonically with the others.' },
  { id: 'mus-95', category: 'music', difficulty: 'hard', question: 'What is the standard concert pitch frequency that most orchestras tune to?', answer: '440 Hz (A above middle C)', options: ['432 Hz', '440 Hz (A above middle C)', '444 Hz', '436 Hz'], explanation: 'A440 was adopted as the international standard in 1955, though it had been widely used since the early 20th century. Historically, concert pitch varied significantly — in the Baroque era, it was often lower, around 415 Hz.' },
  { id: 'mus-96', category: 'music', difficulty: 'hard', question: 'What rapper released "Ready to Die" in 1994 and was murdered in Los Angeles in 1997?', answer: 'The Notorious B.I.G.', options: ['Tupac Shakur', 'The Notorious B.I.G.', 'Big L', 'Big Pun'], explanation: 'The Notorious B.I.G. (Christopher Wallace, also known as Biggie Smalls) was shot in a drive-by shooting in March 1997, six months after Tupac Shakur\'s murder. Both cases remained unsolved for decades.' },
  { id: 'mus-97', category: 'music', difficulty: 'hard', question: 'What Gil Scott-Heron spoken word piece from 1970 is considered a precursor to hip hop?', answer: 'The Revolution Will Not Be Televised', options: ['The Revolution Will Not Be Televised', 'Home Is Where the Hatred Is', 'Whitey on the Moon', 'Winter in America'], explanation: 'Gil Scott-Heron\'s piece combined spoken word poetry with percussion and was a sharp critique of mass media and consumerism. It influenced the development of hip hop and socially conscious rap.' },
  { id: 'mus-98', category: 'music', difficulty: 'hard', question: 'What system of music notation, using do-re-mi syllables, was developed by an 11th-century Benedictine monk?', answer: 'Solmization (by Guido d\'Arezzo)', options: ['Neume notation', 'Solmization (by Guido d\'Arezzo)', 'Tablature', 'The Guidonian hand'], explanation: 'Guido d\'Arezzo derived the syllable names from the first syllables of each line of the Latin hymn "Ut queant laxis." The original "ut" was later replaced by "do" in most countries (except France).' },
  { id: 'mus-99', category: 'music', difficulty: 'hard', question: 'What album by Kendrick Lamar won the Pulitzer Prize for Music in 2018, the first non-classical or jazz work to do so?', answer: 'DAMN.', options: ['good kid, m.A.A.d city', 'To Pimp a Butterfly', 'DAMN.', 'Section.80'], explanation: 'DAMN. won the 2018 Pulitzer Prize, with the committee calling it "a virtuosic song collection unified by its vernacular authenticity." This was a groundbreaking moment for hip hop\'s recognition in the academic music establishment.' },
  { id: 'mus-100', category: 'music', difficulty: 'hard', question: 'What is the "circle of fifths" in music theory?', answer: 'A visual representation of the relationships among the 12 tones of the chromatic scale, showing keys arranged by ascending fifths', options: ['A chord progression using only fifth intervals', 'A visual representation of the relationships among the 12 tones of the chromatic scale, showing keys arranged by ascending fifths', 'A series of five scales used in jazz improvisation', 'A compositional technique where melodies are transposed up by fifths'], explanation: 'The circle of fifths arranges all 12 major and minor keys so that adjacent keys differ by one sharp or flat. It is one of the most useful tools in music theory for understanding key signatures, chord progressions, and modulation.' },
  { id: 'mus-101', category: 'music', difficulty: 'hard', question: 'What Beach Boys album, considered Brian Wilson\'s masterpiece, was shelved in 1967 and not officially released until 2004?', answer: 'SMiLE', options: ['Pet Sounds', 'SMiLE', 'Surf\'s Up', 'Sunflower'], explanation: 'SMiLE was intended to follow Pet Sounds but was abandoned due to Wilson\'s mental health struggles and internal band conflicts. Elements appeared on subsequent albums, and Wilson finally completed a solo version, Brian Wilson Presents Smile, in 2004.' },
  { id: 'mus-102', category: 'music', difficulty: 'hard', question: 'What tuning system, used before equal temperament, features pure fifths but results in one very out-of-tune interval called the "wolf fifth"?', answer: 'Pythagorean tuning', options: ['Just intonation', 'Pythagorean tuning', 'Meantone temperament', 'Well temperament'], explanation: 'Pythagorean tuning stacks pure perfect fifths (3:2 ratio) to generate all notes. The problem is that twelve pure fifths don\'t exactly equal seven octaves, leaving a discrepancy called the Pythagorean comma, concentrated in the wolf fifth.' },
  { id: 'mus-103', category: 'music', difficulty: 'hard', question: 'What sampling technique, pioneered by hip hop producers, involves speeding up a soul or R&B vocal sample to create a higher-pitched sound?', answer: 'Chipmunk soul', options: ['Chopping', 'Chipmunk soul', 'Time-stretching', 'Sidechain sampling'], explanation: 'The chipmunk soul technique was popularized by Kanye West, particularly on his debut album The College Dropout (2004). RZA of Wu-Tang Clan and Just Blaze also used similar techniques before it became widely associated with West.' },
  { id: 'mus-104', category: 'music', difficulty: 'hard', question: 'What John Coltrane album, recorded in one session in December 1964, is considered a landmark of spiritual jazz?', answer: 'A Love Supreme', options: ['Giant Steps', 'A Love Supreme', 'My Favorite Things', 'Blue Train'], explanation: 'A Love Supreme is a four-part suite that Coltrane described as a spiritual declaration of his devotion to God. It is divided into four movements: Acknowledgement, Resolution, Pursuance, and Psalm.' },
  { id: 'mus-105', category: 'music', difficulty: 'hard', question: 'What pioneering music technology, introduced by Roland in 1983, allowed electronic instruments from different manufacturers to communicate?', answer: 'MIDI', options: ['MIDI', 'USB Audio', 'S/PDIF', 'ADAT'], explanation: 'MIDI (Musical Instrument Digital Interface) standardized communication between synthesizers, drum machines, and computers. It transmits performance data (notes, velocity, timing) rather than audio, making it extremely efficient and versatile.' },
  { id: 'mus-106', category: 'music', difficulty: 'hard', question: 'What Austrian composer\'s unfinished Eighth Symphony is famously known as the "Unfinished Symphony"?', answer: 'Franz Schubert', options: ['Gustav Mahler', 'Franz Schubert', 'Anton Bruckner', 'Ludwig van Beethoven'], explanation: 'Schubert completed two movements of his Symphony No. 8 in B minor in 1822 but never finished the remaining movements. Why he abandoned it remains one of classical music\'s great mysteries.' },
  { id: 'mus-107', category: 'music', difficulty: 'hard', question: 'What technique in DJing involves manipulating a vinyl record back and forth on a turntable to create rhythmic sounds?', answer: 'Scratching', options: ['Beatmatching', 'Scratching', 'Backspinning', 'Phasing'], explanation: 'Scratching was pioneered by Grand Wizzard Theodore in the late 1970s, reportedly when he stopped a record with his hand to listen to his mother. Grandmaster Flash and DJ Jazzy Jeff further developed the technique.' },
  { id: 'mus-108', category: 'music', difficulty: 'hard', question: 'What Stravinsky ballet caused a riot at its 1913 Paris premiere due to its dissonant music and avant-garde choreography?', answer: 'The Rite of Spring', options: ['The Firebird', 'Petrushka', 'The Rite of Spring', 'Apollo'], explanation: 'The Rite of Spring\'s premiere at the Theatre des Champs-Elysees on May 29, 1913 is one of music history\'s most famous scandals. The audience reportedly fought among themselves, and police had to be called to restore order.' },
  { id: 'mus-109', category: 'music', difficulty: 'hard', question: 'What is the name of the 24-note microtonal system used in traditional Arabic and Turkish music?', answer: 'Quarter-tone system', options: ['Raga system', 'Quarter-tone system', 'Just intonation', 'Slendro'], explanation: 'Arabic maqam music divides the octave into 24 quarter tones, giving access to intervals not available in Western 12-tone equal temperament. This allows for the distinctive ornamental and melodic characteristics of Middle Eastern music.' },
  { id: 'mus-110', category: 'music', difficulty: 'hard', question: 'What singer-songwriter\'s album "Blue" (1971) is considered one of the most influential singer-songwriter albums of all time?', answer: 'Joni Mitchell', options: ['Carole King', 'Joni Mitchell', 'Carly Simon', 'Laura Nyro'], explanation: 'Joni Mitchell\'s Blue features sparse arrangements and deeply confessional lyrics about love and loss. Kris Kristofferson reportedly said hearing the album was like "a person bleedingly, I mean, they were so personal."' },
  { id: 'mus-111', category: 'music', difficulty: 'hard', question: 'What production technique, pioneered by Phil Spector in the 1960s, layers multiple instruments to create a dense, reverberant sound?', answer: 'Wall of Sound', options: ['Overdubbing', 'Wall of Sound', 'Lo-fi production', 'Reverb chamber'], explanation: 'Spector\'s Wall of Sound used large ensembles with doubled or tripled instruments, extensive echo, and Gold Star Studios\' echo chambers. The technique is heard on classics like The Ronettes\' "Be My Baby" and The Righteous Brothers\' "You\'ve Lost That Lovin\' Feelin\'."' },
  { id: 'mus-112', category: 'music', difficulty: 'hard', question: 'What 1985 charity concert, held simultaneously in London and Philadelphia, was organized to raise funds for Ethiopian famine relief?', answer: 'Live Aid', options: ['Band Aid', 'Live Aid', 'Farm Aid', 'Live 8'], explanation: 'Live Aid was organized by Bob Geldof and Midge Ure and broadcast to an estimated 1.9 billion viewers worldwide. Queen\'s performance at Wembley Stadium is widely considered one of the greatest live performances in rock history.' },
  { id: 'mus-113', category: 'music', difficulty: 'hard', question: 'What is the lowest-pitched instrument in a standard symphony orchestra?', answer: 'Contrabassoon', options: ['Tuba', 'Double bass', 'Contrabassoon', 'Bass trombone'], explanation: 'The contrabassoon sounds an octave lower than the standard bassoon and can reach notes lower than the tuba or double bass. Its lowest note, B-flat 0, vibrates at about 29 Hz, near the lower limit of human hearing.' },
  { id: 'mus-114', category: 'music', difficulty: 'hard', question: 'What Nigerian musician is considered the creator of Afrobeat, blending West African music with jazz, funk, and political lyrics?', answer: 'Fela Kuti', options: ['King Sunny Ade', 'Fela Kuti', 'Burna Boy', 'Youssou N\'Dour'], explanation: 'Fela Kuti developed Afrobeat in Lagos in the late 1960s and used his music as a weapon against Nigeria\'s military government. His band Africa 70 performed songs that often ran 20-30 minutes, featuring complex polyrhythmic arrangements.' },
  { id: 'mus-115', category: 'music', difficulty: 'hard', question: 'What modal jazz technique, used extensively on Miles Davis\'s Kind of Blue, bases improvisation on scales rather than chord changes?', answer: 'Modal jazz', options: ['Bebop', 'Modal jazz', 'Free jazz', 'Cool jazz'], explanation: 'Modal jazz freed soloists from navigating rapid chord changes, allowing more melodic exploration. Bill Evans, John Coltrane, and Cannonball Adderley on Kind of Blue demonstrated how this approach created a more spacious, contemplative sound.' },
  { id: 'mus-116', category: 'music', difficulty: 'hard', question: 'What is the name of the Nashville-based radio show that has broadcast country music since 1925, making it one of the longest-running radio programs?', answer: 'Grand Ole Opry', options: ['WSM Barn Dance', 'Grand Ole Opry', 'Prairie Home Companion', 'Austin City Limits'], explanation: 'The Grand Ole Opry began as the WSM Barn Dance on November 28, 1925. It was renamed by announcer George D. Hay, who jokingly said after a classical music program: "For the past hour, we have been listening to music taken largely from Grand Opera; from now on, we will present the Grand Ole Opry."' },
  { id: 'mus-117', category: 'music', difficulty: 'hard', question: 'What concept album by Pink Floyd tells the story of a rock star who builds a metaphorical wall around himself?', answer: 'The Wall', options: ['The Dark Side of the Moon', 'Wish You Were Here', 'The Wall', 'The Final Cut'], explanation: 'The Wall (1979) was largely autobiographical, drawing on Roger Waters\'s experiences with his father\'s death in WWII and the alienation of rock stardom. It was adapted into a film directed by Alan Parker in 1982.' },
  { id: 'mus-118', category: 'music', difficulty: 'hard', question: 'What technique in 12-tone (dodecaphonic) composition, developed by Arnold Schoenberg, treats all 12 chromatic pitches as equal?', answer: 'Serialism (twelve-tone technique)', options: ['Atonality', 'Serialism (twelve-tone technique)', 'Aleatoricism', 'Neo-classicism'], explanation: 'Schoenberg developed the twelve-tone technique in the early 1920s as a systematic method for organizing atonal music. A tone row uses all 12 notes of the chromatic scale in a fixed order, and the row can be transposed, inverted, or played in retrograde.' },
  { id: 'mus-119', category: 'music', difficulty: 'hard', question: 'What Grammy category did Jethro Tull controversially win in 1989, beating Metallica?', answer: 'Best Hard Rock/Metal Performance', options: ['Best Rock Album', 'Best Hard Rock/Metal Performance', 'Best Rock Performance', 'Album of the Year'], explanation: 'Jethro Tull\'s win for their album Crest of a Knave over Metallica\'s ...And Justice for All is considered one of the most controversial Grammy decisions ever. The backlash led the Recording Academy to split the category into separate Hard Rock and Metal awards.' },
  { id: 'mus-120', category: 'music', difficulty: 'hard', question: 'What is the term for the wobbling effect produced by rapidly alternating between two adjacent notes?', answer: 'Trill', options: ['Vibrato', 'Trill', 'Tremolo', 'Glissando'], explanation: 'A trill alternates rapidly between a note and the note above it (usually a half or whole step). Vibrato, by contrast, is a slight fluctuation of pitch on a single note, while tremolo is a rapid repetition of the same note.' },
  { id: 'mus-121', category: 'music', difficulty: 'hard', question: 'What recording studio, located at 2648 West Grand Boulevard in Detroit, was the original home of Motown Records?', answer: 'Hitsville U.S.A.', options: ['Sun Studio', 'Hitsville U.S.A.', 'Muscle Shoals Sound Studio', 'Gold Star Studios'], explanation: 'Berry Gordy purchased the house in 1959 and converted it into a recording studio, famously hanging a "Hitsville U.S.A." sign on the facade. Today it operates as the Motown Museum, attracting hundreds of thousands of visitors annually.' },
  { id: 'mus-122', category: 'music', difficulty: 'hard', question: 'What vocal technique, common in yodeling, Swiss singing, and some pop music, involves rapidly switching between chest voice and head voice?', answer: 'Register break (or vocal break)', options: ['Melisma', 'Register break (or vocal break)', 'Falsetto', 'Belting'], explanation: 'The deliberate use of the register break is central to yodeling traditions in the Swiss Alps and also appears in country music (Hank Williams, Jewel) and contemporary pop. Cher\'s "Believe" (1998) famously simulated an exaggerated version using Auto-Tune.' },
  { id: 'mus-123', category: 'music', difficulty: 'hard', question: 'What 1966 Beach Boys album is widely considered one of the greatest and most innovative pop albums ever made?', answer: 'Pet Sounds', options: ['Surfin\' USA', 'Pet Sounds', 'Today!', 'Summer Days (And Summer Nights!!)'], explanation: 'Pet Sounds was Brian Wilson\'s response to hearing The Beatles\' Rubber Soul. Paul McCartney has said that Pet Sounds was the primary inspiration for Sgt. Pepper\'s Lonely Hearts Club Band, creating a creative back-and-forth between the two bands.' },
  { id: 'mus-124', category: 'music', difficulty: 'hard', question: 'What Indian stringed instrument, prominently used by Ravi Shankar, influenced George Harrison and the psychedelic rock era?', answer: 'Sitar', options: ['Veena', 'Sitar', 'Sarod', 'Tambura'], explanation: 'The sitar has movable frets, sympathetic strings, and a distinctive buzzing timbre. George Harrison studied with Ravi Shankar and introduced the sitar to rock music on The Beatles\' "Norwegian Wood" (1965).' },
  { id: 'mus-125', category: 'music', difficulty: 'hard', question: 'What US law, passed in 1992, required royalty payments on digital audio recording devices and media to compensate for home copying?', answer: 'The Audio Home Recording Act', options: ['The Digital Millennium Copyright Act', 'The Audio Home Recording Act', 'The Sound Recording Act', 'The Digital Performance Right Act'], explanation: 'The Audio Home Recording Act of 1992 required manufacturers and importers of digital audio recording devices and blank media to pay royalties to copyright holders. In exchange, consumers were protected from infringement lawsuits for noncommercial home copying. Traditional AM/FM radio still does not pay performance royalties to recording artists in the US, only to songwriters, unlike most other countries.' },
]
